def lookup(key=None, *, legacy_key=None, namespace=None):
    if (key is None) == (legacy_key is None):
        raise ValueError("provide exactly one of key or legacy_key")
    resolved = key if key is not None else legacy_key
    result = {"key": resolved}
    if namespace is not None:
        if type(namespace) is not str:
            raise TypeError("namespace must be a string")
        if not namespace:
            raise ValueError("namespace must not be empty")
        result["namespace"] = namespace
    return result

